import binascii, sys, unicodedata
print(sys.version)
print(unicodedata.unidata_version, sys.byteorder)
for checksum in (binascii.crc32, binascii.crc_hqx):
    print(checksum.__name__, repr(checksum.__doc__), repr(checksum.__text_signature__))
    data = bytearray(b'A')
    events = []
    class Seed:
        def __index__(self):
            events.append('index')
            try:
                data.extend(b'B')
            except BufferError:
                events.append('pinned')
            else:
                raise AssertionError('buffer not pinned')
            data[0] = 66
            return -(1 << 100) - 1
    result = checksum(data, Seed())
    assert result == checksum(b'B', -1)
    data.extend(b'C')
    print(result, events, bytes(data))
    for args in [(), (b'',), (b'', 0, 1), (None, 0), ('', 0), (b'', None), (b'', 2**100)]:
        try:
            print(repr(args), checksum(*args))
        except Exception as error:
            print(repr(args), type(error).__name__, error.args)
    try:
        checksum(data=b'', crc=0)
    except TypeError as error:
        print(error.args)
